/*
 * Application icon family (creator 'WRDL', file type 'APPL').
 *
 * Designed in Icon Machine and exported as a resource file (see
 * project chat); these are the exact bytes it produced for every
 * classic icon-family type plus a full 'icns' container, extracted
 * directly from that resource fork -- no re-encoding on our side,
 * so the color-table-indexed variants (icl4/icl8/icm4/icm8/ics4/
 * ics8) are correctly mapped by the tool itself. il32/l8mk/is32/
 * s8mk (32x32 and 16x16 truecolor + mask) are pulled out of the
 * icns container and duplicated as standalone top-level resources
 * too, since PlotIconID() looks those up directly and doesn't
 * necessarily dig into an icns container the way the Finder does.
 */

